import { z } from "zod";
import {
  CHAT_GROUP_DESCRIPTION_MAX_LENGTH,
  CHAT_GROUP_INVITES_PER_CALL,
  CHAT_GROUP_NAME_MAX_LENGTH,
  CHAT_GROUP_NAME_MIN_LENGTH,
  CHAT_GROUP_SCOPES,
  CHAT_GROUP_VISIBILITIES,
  CHAT_INBOXES,
  CHAT_MESSAGE_MAX_LENGTH,
  CHAT_REPORT_ACTIONS,
  DEFAULT_PAGE_SIZE,
  MAX_PAGE_SIZE,
  REPORT_REASONS,
  REPORT_STATUSES,
} from "../constants";
import { cursorQuerySchema, isoDateTimeSchema, optionalTrimmed, pageQuerySchema, uuidSchema } from "./common";

/** Generated by the client for each message, so a retry after a lost response can't send it twice. */
export const chatClientKeySchema = z.string().regex(/^[A-Za-z0-9_-]{8,64}$/, "Use 8 to 64 letters, digits, hyphens or underscores");

// A NUL would otherwise reach Postgres and fail the send. Newlines and tabs are kept.
// eslint-disable-next-line no-control-regex -- matching control characters is the point
const CONTROL_CHARACTERS = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;

/** Zero-width and other invisible characters count as nothing, or a message could be an empty bubble. */
export const VISIBLE_CHARACTER = /[^\s\u00AD\u200B-\u200F\u2028-\u202F\u2060-\u206F\uFEFF]/;

/** Drops control characters other than newlines and tabs, then trims: what every piece of chat text is cleaned with. */
export const stripControlCharacters = (v: string): string => v.replace(CONTROL_CHARACTERS, "").trim();

export const chatMessageBodySchema = z
  .string()
  .transform(stripControlCharacters)
  .pipe(z.string().min(1, "Write a message").max(CHAT_MESSAGE_MAX_LENGTH).regex(VISIBLE_CHARACTER, "Write a message"));

export const chatMessageCreateSchema = z.object({ body: chatMessageBodySchema, clientKey: chatClientKeySchema });
export type ChatMessageCreateInput = z.input<typeof chatMessageCreateSchema>;

export const chatDirectCreateSchema = chatMessageCreateSchema.extend({ membershipId: uuidSchema });
export type ChatDirectCreateInput = z.input<typeof chatDirectCreateSchema>;

export const chatConversationsQuerySchema = cursorQuerySchema.extend({ inbox: z.enum(CHAT_INBOXES).default("MAIN") });
export type ChatConversationsQuery = z.infer<typeof chatConversationsQuerySchema>;

/** `cursor` pages back through older messages, newest first. `afterSeq` fetches what came after, oldest first. */
export const chatMessagesQuerySchema = cursorQuerySchema
  .extend({ afterSeq: z.string().max(20).optional() })
  .refine((q) => !(q.cursor && q.afterSeq !== undefined), "Use cursor or afterSeq, not both");
export type ChatMessagesQuery = z.infer<typeof chatMessagesQuerySchema>;

export const chatReadSchema = z.object({ seq: z.number().int().min(0).max(2147483647) });
export type ChatReadInput = z.infer<typeof chatReadSchema>;

/** `until: null` unmutes. */
export const chatMuteSchema = z.object({ until: isoDateTimeSchema.nullable() });
export type ChatMuteInput = z.infer<typeof chatMuteSchema>;

export const chatBlockCreateSchema = z.object({ membershipId: uuidSchema });
export type ChatBlockCreateInput = z.infer<typeof chatBlockCreateSchema>;

export const chatReportCreateSchema = z.object({ reason: z.enum(REPORT_REASONS), details: optionalTrimmed(1000) });
export type ChatReportCreateInput = z.input<typeof chatReportCreateSchema>;

export const chatGroupNameSchema = z
  .string()
  .transform(stripControlCharacters)
  .pipe(z.string().min(CHAT_GROUP_NAME_MIN_LENGTH, `Use at least ${CHAT_GROUP_NAME_MIN_LENGTH} characters`).max(CHAT_GROUP_NAME_MAX_LENGTH).regex(VISIBLE_CHARACTER, "Give the group a name"));

/** Empty clears it. */
export const chatGroupDescriptionSchema = z
  .string()
  .transform(stripControlCharacters)
  .pipe(z.string().max(CHAT_GROUP_DESCRIPTION_MAX_LENGTH))
  .transform((v) => (VISIBLE_CHARACTER.test(v) ? v : null))
  .nullable();

export const chatGroupCreateSchema = z.object({
  name: chatGroupNameSchema,
  description: chatGroupDescriptionSchema.optional().transform((v) => v ?? null),
  visibility: z.enum(CHAT_GROUP_VISIBILITIES, { error: "Choose who can join" }),
});
export type ChatGroupCreateInput = z.input<typeof chatGroupCreateSchema>;

/**
 * Edits the name and description, or archives the group, never both at once. Strict, so a visibility that comes along is
 * refused rather than quietly ignored: it never changes, because turning an invite-only group open would expose its history.
 */
export const chatGroupUpdateSchema = z
  .object({ name: chatGroupNameSchema.optional(), description: chatGroupDescriptionSchema.optional(), archived: z.literal(true).optional() })
  .strict()
  .refine((v) => (v.archived === true) !== (v.name !== undefined || v.description !== undefined), "Change the name or description, or archive the group");
export type ChatGroupUpdateInput = z.input<typeof chatGroupUpdateSchema>;

export const chatGroupsQuerySchema = cursorQuerySchema.extend({ scope: z.enum(CHAT_GROUP_SCOPES).default("DISCOVER"), q: z.string().trim().max(80).optional() });
export type ChatGroupsQuery = z.infer<typeof chatGroupsQuerySchema>;

export const chatGroupInviteSchema = z.object({
  membershipIds: z
    .array(uuidSchema)
    .min(1, "Choose someone to invite")
    .max(CHAT_GROUP_INVITES_PER_CALL, `Invite up to ${CHAT_GROUP_INVITES_PER_CALL} people at a time`)
    .transform((ids) => [...new Set(ids)]),
});
export type ChatGroupInviteInput = z.input<typeof chatGroupInviteSchema>;

export const chatGroupCandidatesQuerySchema = z.object({ q: z.string().trim().max(80).optional(), limit: z.coerce.number().int().min(1).max(MAX_PAGE_SIZE).default(DEFAULT_PAGE_SIZE) });
export type ChatGroupCandidatesQuery = z.infer<typeof chatGroupCandidatesQuerySchema>;

export const chatGroupMemberParamsSchema = z.object({ id: uuidSchema, membershipId: uuidSchema });

export const adminChatReportsQuerySchema = pageQuerySchema.extend({ status: z.enum(REPORT_STATUSES).default("OPEN") });
export type AdminChatReportsQuery = z.infer<typeof adminChatReportsQuerySchema>;

export const chatReportResolveSchema = z.object({ action: z.enum(CHAT_REPORT_ACTIONS), note: optionalTrimmed(500) });
export type ChatReportResolveInput = z.infer<typeof chatReportResolveSchema>;
